use vstd::prelude::*;

verus! {

/// Spec function to lowercase an ASCII character according to the given rule:
/// - 'A'..'Z' map to 'a'..'z' respectively
/// - all other chars remain unchanged
spec fn ascii_lowercase(c: char) -> char {
    if 'A' <= c && c <= 'Z' {
        (c as u8 + 32) as char
    } else {
        c
    }
}

/// Spec predicate that a vector of chars (text) is a case-insensitive palindrome,
/// using ascii_lowercase mapping.
/// For all i < text.len(), ascii_lowercase(text[i]) == ascii_lowercase(text[text.len() - 1 - i])
spec fn is_palindrome_spec(text: Seq<char>) -> bool {
    forall |i: int| 0 <= i && i < text.len() ==> 
        ascii_lowercase(text.index(i)) == ascii_lowercase(text.index(text.len() - 1 - i))
}

fn is_palindrome(text: Vec<char>) -> (result: bool)
    ensures
        result == is_palindrome_spec(text.as_seq())
{
    let len = text.len();
    if len <= 1 {
        return true;
    }
    let mut left: usize = 0;
    let mut right: usize = len - 1;
    while left < right
        invariant
            left <= right + 1,
            right < len,
            // the part checked so far is palindrome according to ascii_lowercase
            forall |i: int| 0 <= i && i < left as int ==>
                ascii_lowercase(text[i]) == ascii_lowercase(text[len - 1 - i]),
        decreases right - left,
    {
        let c_left = text[left];
        let c_right = text[right];
        if ascii_lowercase(c_left) != ascii_lowercase(c_right) {
            return false;
        }
        left += 1;
        right -= 1;
    }
    true
}

}
